//! The Rooms failure codes the terminal clients branch on, one generated file
//! per language beside the shared demo helpers that read them.
use rooms_application::failure::FailureCode;
use std::path::PathBuf;

const HEADER: &str = "Generated by rooms-application/examples/browser_metadata.rs. Do not edit.";
const SAID: &str = "The Rooms failure codes enter-or-open branches on, from `FailureCode`.";
/// Each code's name in snake case. Every language spells its constant from it.
const CODES: [(&str, FailureCode); 2] = [
	("no_such_room", FailureCode::NoSuchRoom),
	("room_exists", FailureCode::RoomExists),
];

pub fn generate() -> Vec<(PathBuf, String)> {
	let demo = PathBuf::from(concat!(env!("CARGO_MANIFEST_DIR"), "/../../../_demo"));
	let mut python = format!("# {HEADER}\n\"\"\"{SAID}\"\"\"\n\n");
	let mut racket = format!("#lang racket/base\n;; {HEADER}\n;; {SAID}\n\n(provide");
	let mut rust = format!("// {HEADER}\n//! {SAID}\n\n");
	let mut zig = format!("// {HEADER}\n//! {SAID}\n\n");
	for (name, _) in CODES {
		racket.push_str(&format!(" {}", name.replace('_', "-").to_uppercase()));
	}
	racket.push_str(")\n\n");
	for (name, code) in CODES {
		let wire = code.wire();
		let upper = name.to_uppercase();
		python.push_str(&format!("{upper} = \"{wire}\"\n"));
		racket.push_str(&format!("(define {} \"{wire}\")\n", upper.replace('_', "-")));
		rust.push_str(&format!("pub const {upper}: &str = \"{wire}\";\n"));
		zig.push_str(&format!("pub const {name} = \"{wire}\";\n"));
	}
	vec![
		(demo.join("rooms_codes.py"), python),
		(demo.join("rooms_codes.rkt"), racket),
		(demo.join("rooms_codes.rs"), rust),
		(demo.join("zig/rooms_codes.zig"), zig),
	]
}
